$$C{{dV} \over {dt}} = - {g_L}(V - {E_L}) + {g_L}{_T}\exp \left( {{{V - {V_T}} \over {{_T}}}} \right) + I - w$$
\end{document}, \documentclass[12pt]{minimal}
